workspace/library/papers.jsonl:15:{"id": "W3005819298", "title": "Spark plasma sintering plus heat-treatment of Ta-doped Li7La3Zr2O12 solid electrolyte and its ionic conductivity", "authors": ["Jiali Xue", "Kuibao Zhang", "Daimeng Chen", "Jianjun Zeng", "Baozhu Luo"], "year": 2020, "venue": "Materials Research Express", "doi": "10.1088/2053-1591/ab7618", "arxiv_id": null, "url": "https://doi.org/10.1088/2053-1591/ab7618", "pdf_url": "https://iopscience.iop.org/article/10.1088/2053-1591/ab7618/pdf", "abstract": "Abstract Ta-doped Li7La3Zr2O12 (Ta-LLZO) solid electrolyte ceramics were synthesized by solid-state sintering, spark plasma sintering (SPS) and SPS plus heat-treatment (two-step method) using LiOH·H2O, La2O3, ZrO2 and Ta2O5 as the raw materials. The Ta-LLZO samples prepared from these three routes are all in cubic phase structure. However, the solid-state method results in Ta-LLZO samples with different particle sizes and porous morphology, while the samples prepared by SPS route contain fewer internal voids and smaller particle size. The two-step method not only retains the high compactness of SPS samples, but also the increment of grain size. The SEM results demonstrate that Ta-LLZO sintered by the two-step method shows optimal electrical properties. And the total ionic conductivity is 4.6 × 10−3 S cm−1 at 150 °C and the activation energy is calculated to be 0.38 eV.", "citation_count": 34, "sources": ["openalex"]}
workspace/library/papers.jsonl:17:{"id": "W2281878692", "title": "Ionic Conductivity and Air Stability of Al-Doped Li 7 La 3 Zr 2 O 12 Sintered in Alumina and Pt Crucibles", "authors": ["Wenhao Xia", "Biyi Xu", "Huanan Duan", "Yiping Guo", "Hongmei Kang", "Hua Li", "Hezhou Liu"], "year": 2016, "venue": "ACS Applied Materials & Interfaces", "doi": "10.1021/acsami.5b12186", "arxiv_id": null, "url": "https://doi.org/10.1021/acsami.5b12186", "pdf_url": null, "abstract": "Li7La3Zr2O12 (LLZO) is a promising electrolyte material for all-solid-state battery due to its high ionic conductivity and good stability with metallic lithium. In this article, we studied the effect of crucibles on the ionic conductivity and air stability by synthesizing 0.25Al doped LLZO pellets in Pt crucibles and alumina crucibles, respectively. The results show that the composition and microstructure of the pellets play important roles influencing the ionic conductivity, relative density, and air stability. Specifically, the 0.25Al-LLZO pellets sintered in Pt crucibles exhibit a high relative density (∼96%) and high ionic conductivity (4.48 × 10(-4) S cm(-1)). The ionic conductivity maintains 3.6 × 10(-4) S cm(-1) after 3-month air exposure. In contrast, the ionic conductivity of the pellets from alumina crucibles is about 1.81 × 10(-4) S cm(-1) and drops to 2.39 × 10(-5) S cm(-1) 3 months later. The large grains and the reduced grain boundaries in the pellets sintered in Pt crucibles are favorable to obtain high ionic conductivity and good air stability. X-ray photoelectron spectroscopy (XPS) and Raman spectroscopy results suggest that the formation of Li2CO3 on the pellet surface is probably another main reason, which is also closely related to the relative density and the amount of grain boundary within the pellets. This work stresses the importance of synthesis parameters, crucibles included, to obtain the LLZO electrolyte with high ionic conductivity and good air stability.", "citation_count": 305, "_query": "LLZO relative density ionic conductivity microstructure", "sources": ["openalex"]}
workspace/library/papers.jsonl:18:{"id": "W2913888676", "title": "Manipulating Li2O atmosphere for sintering dense Li7La3Zr2O12 solid electrolyte", "authors": ["Xiao Huang", "Yang Lu", "Zhen Song", "Kun Rui", "Qingsong Wang", "Tongping Xiu", "Michael E. Badding", "Zhaoyin Wen"], "year": 2019, "venue": "Energy storage materials", "doi": "10.1016/j.ensm.2019.01.018", "arxiv_id": null, "url": "https://doi.org/10.1016/j.ensm.2019.01.018", "pdf_url": null, "abstract": null, "citation_count": 207, "_query": "LLZO relative density ionic conductivity microstructure", "sources": ["openalex"]}
